import Cocoa

let findElementsWithTitle = { (title: String) -> [NSAccessibilityElement] in
    var results: [NSAccessibilityElement] = []

    guard let focusedApp = NSWorkspace.shared.frontmostApplication else {
        return results
    }

    guard let appElement = AXUIElementCreateApplication(focusedApp.processIdentifier) as AXUIElement? else {
        return results
    }

    func search(_ element: AXUIElement) {
        if let elementTitle = try? element.accessibilityAttributeValue(.title) as? String,
           elementTitle == title {
            if let nativeElement = element as? NSAccessibilityElement {
                results.append(nativeElement)
            }
        }

        if let children = try? element.accessibilityAttributeValue(.children) as? [AXUIElement] {
            for child in children {
                search(child)
            }
        }
    }

    search(appElement)
    return results
}

// Try to find and interact with the dialog
print("Attempting to interact with accessibility elements")
EOF

